const ORIGINAL_DOCX_BASE64 = "";
/* ==========================================================================
   عُقُودك الذكية - Dalil-In Original DOCX & PDF Template Engine
   ========================================================================== */

document.addEventListener('DOMContentLoaded', () => {

    const MAX_IMAGES = 5;
    let uploadedImages = [];

    // Master Contract State
    let contractData = {
        ref_no: '---/26',
        date: new Date().toISOString().split('T')[0].replace(/-/g, '/'),
        second_party_name: '',
        second_party_address: '',
        second_party_cr: '',
        iban_number: '',
        commission_percent: '10%',
        arbitration_rules: 'قواعد مركز الكويت للتحكيم التجاري',
        signatory_name: '',
        payments: {
            pay_knet: true,
            pay_mastercard: true,
            pay_visa: true,
            pay_applepay: true,
            pay_googlepay: true
        }
    };

    let customFields = [];

    // DOM Elements
    const dropzone = document.getElementById('dropzone');
    const fileInput = document.getElementById('fileInput');
    const imagesCountText = document.getElementById('imagesCountText');
    const imagesGallery = document.getElementById('imagesGallery');
    const btnClearAll = document.getElementById('btnClearAll');

    // Word Download Buttons
    const btnDownloadBlankDocx = document.getElementById('btnDownloadBlankDocx');
    const btnDownloadBlankDocxFooter = document.getElementById('btnDownloadBlankDocxFooter');
    const btnDownloadMasterDocx = document.getElementById('btnDownloadMasterDocx');
    const btnDownloadMasterDocx2 = document.getElementById('btnDownloadMasterDocx2');
    const btnDownloadSingleModalDocx = document.getElementById('btnDownloadSingleModalDocx');
    const btnDownloadBlankFromModal = document.getElementById('btnDownloadBlankFromModal');

    // PDF Download Buttons
    const btnDownloadMasterPdf = document.getElementById('btnDownloadMasterPdf');
    const btnDownloadMasterPdf2 = document.getElementById('btnDownloadMasterPdf2');
    const btnDownloadPdfModal = document.getElementById('btnDownloadPdfModal');
    const btnDownloadBlankPdf = document.getElementById('btnDownloadBlankPdf');
    const btnDownloadBlankPdfFooter = document.getElementById('btnDownloadBlankPdfFooter');
    const btnDownloadBlankPdfFromModal = document.getElementById('btnDownloadBlankPdfFromModal');

    // Modal & Preview Buttons
    const btnPreviewMasterContract = document.getElementById('btnPreviewMasterContract');
    const btnAddCustomField = document.getElementById('btnAddCustomField');
    const previewModal = document.getElementById('previewModal');
    const btnCloseModal = document.getElementById('btnCloseModal');
    const btnCloseModal2 = document.getElementById('btnCloseModal2');
    const contractPaperRender = document.getElementById('contractPaperRender');

    // Demo Buttons
    const btnDemo1 = document.getElementById('btnDemo1');
    const btnDemo2 = document.getElementById('btnDemo2');
    const btnDemo3 = document.getElementById('btnDemo3');

    // Toast Notification System
    function showToast(message, type = 'info') {
        const toastContainer = document.getElementById('toastContainer');
        if (!toastContainer) return;
        const toast = document.createElement('div');
        toast.className = 'toast toast-' + type;
        let iconClass = 'fa-info-circle';
        if (type === 'success') iconClass = 'fa-circle-check';
        if (type === 'error') iconClass = 'fa-circle-exclamation';
        
        toast.innerHTML = '<i class="fa-solid ' + iconClass + '"></i> <span>' + message + '</span>';
        toastContainer.appendChild(toast);
        
        setTimeout(() => {
            toast.style.opacity = '0';
            toast.style.transform = 'translateX(-100%)';
            setTimeout(() => toast.remove(), 300);
        }, 3500);
    }

    // Convert Base64 to ArrayBuffer
    function base64ToArrayBuffer(base64) {
        const binaryString = atob(base64);
        const len = binaryString.length;
        const bytes = new Uint8Array(len);
        for (let i = 0; i < len; i++) {
            bytes[i] = binaryString.charCodeAt(i);
        }
        return bytes.buffer;
    }

    // Get Docx ArrayBuffer
    async function getOriginalDocxBuffer() {
        if (typeof ORIGINAL_DOCX_BASE64 !== 'undefined' && ORIGINAL_DOCX_BASE64 && ORIGINAL_DOCX_BASE64.length > 100) {
            return base64ToArrayBuffer(ORIGINAL_DOCX_BASE64);
        }
        const res = await fetch('./البحرين.docx');
        return await res.arrayBuffer();
    }

    // Attach Inputs to State
    document.querySelectorAll('.contract-field').forEach(input => {
        input.addEventListener('input', (e) => {
            const key = e.target.dataset.key;
            contractData[key] = e.target.value;
        });
    });

    document.querySelectorAll('.payment-check').forEach(chk => {
        chk.addEventListener('change', (e) => {
            const key = e.target.dataset.key;
            contractData.payments[key] = e.target.checked;
        });
    });

    // Upload & Drag Drop
    if (dropzone) {
        dropzone.addEventListener('click', () => {
            if (fileInput) fileInput.click();
        });

        ['dragenter', 'dragover'].forEach(eventName => {
            dropzone.addEventListener(eventName, (e) => {
                e.preventDefault();
                dropzone.classList.add('dragover');
            });
        });

        ['dragleave', 'drop'].forEach(eventName => {
            dropzone.addEventListener(eventName, (e) => {
                e.preventDefault();
                dropzone.classList.remove('dragover');
            });
        });

        dropzone.addEventListener('drop', (e) => {
            handleFilesUpload(e.dataTransfer.files);
        });
    }

    if (fileInput) {
        fileInput.addEventListener('change', (e) => {
            handleFilesUpload(e.target.files);
            fileInput.value = '';
        });
    }

    function handleFilesUpload(files) {
        if (!files || files.length === 0) return;

        const currentCount = uploadedImages.length;
        const availableSlots = MAX_IMAGES - currentCount;

        if (availableSlots <= 0) {
            showToast('عفواً، الحد الأقصى لمستندات هذا العقد هو 5 صور فقط.', 'error');
            return;
        }

        const validFiles = Array.from(files).filter(f => f.type.startsWith('image/'));
        const filesToProcess = validFiles.slice(0, availableSlots);

        filesToProcess.forEach(file => {
            const reader = new FileReader();
            reader.onload = (e) => {
                const imgObj = {
                    id: 'img_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4),
                    title: file.name,
                    url: e.target.result,
                    status: 'processing'
                };
                uploadedImages.push(imgObj);
                renderGallery();
                processOCR(imgObj);
            };
            reader.readAsDataURL(file);
        });
    }

    async function processOCR(imgObj) {
        try {
            let extractedText = '';
            if (window.Tesseract) {
                const res = await window.Tesseract.recognize(imgObj.url, 'ara+eng');
                extractedText = res.data.text || '';
            }

            imgObj.status = 'completed';
            renderGallery();

            parseDalilInInformation(extractedText);
            syncStateToForm();
            showToast('تم استخراج ودمج البيانات من "' + imgObj.title + '" بنجاح!', 'success');

        } catch (e) {
            console.error('OCR Error:', e);
            imgObj.status = 'completed';
            renderGallery();
        }
    }

    function parseDalilInInformation(text) {
        if (!text) return;

        const refM = text.match(/(REF|الإشارة|مرجع)[:\s]*([0-9\/-]+)/i);
        if (refM && !contractData.ref_no) contractData.ref_no = refM[2];

        const dateM = text.match(/(\d{4}[\/\.-]\d{1,2}[\/\.-]\d{1,2})|(\d{1,2}[\/\.-]\d{1,2}[\/\.-]\d{4})/);
        if (dateM && (!contractData.date || contractData.date.includes('2026'))) contractData.date = dateM[0];

        const nameM = text.match(/(الطرف الثاني|السادة|اسم الشركة|المشترك)[:\s]+([^\n\r\d\.\,]+)/i);
        if (nameM && nameM[2] && !contractData.second_party_name) {
            contractData.second_party_name = nameM[2].trim();
        }

        const crM = text.match(/(سجل تجاري|رقم السجل|Registration No|CR)[:\s]*([0-9]{5,14})/i);
        if (crM && !contractData.second_party_cr) {
            contractData.second_party_cr = crM[2];
        }

        const ibanM = text.match(/(IBAN|آيبان|الحساب البنكي)[:\s]*([A-Z0-9\s]{15,34})/i) || text.match(/\b(KW|SA|AE|BH)[0-9]{2}[A-Z0-9]{10,30}\b/i);
        if (ibanM && !contractData.iban_number) {
            contractData.iban_number = (ibanM[2] || ibanM[0]).replace(/\s+/g, '');
        }

        const commM = text.match(/(نسبة|commission)[:\s]*([0-9\.]+\s*%)/i);
        if (commM && !contractData.commission_percent) {
            contractData.commission_percent = commM[2];
        }

        const addrM = text.match(/(العنوان|Located at)[:\s]*([^\n\r]+)/i);
        if (addrM && addrM[2] && !contractData.second_party_address) {
            contractData.second_party_address = addrM[2].trim();
        }
    }

    function syncStateToForm() {
        Object.keys(contractData).forEach(key => {
            if (key !== 'payments') {
                const el = document.querySelector('.contract-field[data-key="' + key + '"]');
                if (el && contractData[key]) el.value = contractData[key];
            }
        });

        if (!contractData.signatory_name && contractData.second_party_name) {
            contractData.signatory_name = contractData.second_party_name;
            const sigEl = document.querySelector('.contract-field[data-key="signatory_name"]');
            if (sigEl) sigEl.value = contractData.second_party_name;
        }
    }

    function renderGallery() {
        if (imagesCountText) imagesCountText.textContent = uploadedImages.length + ' من ' + MAX_IMAGES + ' صور مرفوعة';
        if (!imagesGallery) return;

        if (uploadedImages.length === 0) {
            imagesGallery.innerHTML = '<div class="empty-state" id="emptyState" style="padding: 30px 10px;"><div class="empty-icon"><i class="fa-solid fa-images"></i></div><h4 style="font-size: 1rem; color: var(--text-muted);">لم يتم رفع صور بعد</h4><p style="font-size: 0.82rem;">ارفع حتى 5 صور تحتوي على بيانات اتفاقية دليل ان لاستخراجها</p></div>';
            return;
        }

        imagesGallery.innerHTML = '';
        uploadedImages.forEach((img, idx) => {
            const item = document.createElement('div');
            item.className = 'gallery-item';
            item.innerHTML = '<button class="gallery-delete-btn" data-id="' + img.id + '">&times;</button><div class="gallery-thumb"><img src="' + img.url + '" alt="مستند ' + (idx + 1) + '"></div><div class="gallery-title">مستند ' + (idx + 1) + '</div><div class="gallery-status"><i class="fa-solid ' + (img.status === 'completed' ? 'fa-circle-check' : 'fa-spinner fa-spin') + '"></i> ' + (img.status === 'completed' ? 'تم الفحص' : 'جاري الفحص') + '</div>';
            imagesGallery.appendChild(item);
        });

        document.querySelectorAll('.gallery-delete-btn').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const id = e.currentTarget.dataset.id;
                uploadedImages = uploadedImages.filter(i => i.id !== id);
                renderGallery();
                showToast('تم حذف الصورة.', 'info');
            });
        });
    }

    if (btnClearAll) {
        btnClearAll.addEventListener('click', () => {
            if (uploadedImages.length === 0) return;
            if (confirm('هل أنت تأكد من مسح جميع صور العقد؟')) {
                uploadedImages = [];
                renderGallery();
                showToast('تم مسح الصور.', 'info');
            }
        });
    }

    if (btnAddCustomField) {
        btnAddCustomField.addEventListener('click', () => {
            const name = prompt('أدخل اسم الخيار / الحقل الجديد (مثال: البريد الإلكتروني، رقم الهاتف):');
            if (name && name.trim()) {
                customFields.push({ name: name.trim(), value: '' });
                showToast('تم إضافة الحقل "' + name.trim() + '" للعقد.', 'success');
            }
        });
    }

    // Modal controls
    if (btnPreviewMasterContract) {
        btnPreviewMasterContract.addEventListener('click', () => {
            if (contractPaperRender) contractPaperRender.innerHTML = buildDalilInContractHTML(false);
            if (previewModal) previewModal.classList.add('active');
        });
    }

    function closeModal() { if (previewModal) previewModal.classList.remove('active'); }
    if (btnCloseModal) btnCloseModal.addEventListener('click', closeModal);
    if (btnCloseModal2) btnCloseModal2.addEventListener('click', closeModal);
    if (previewModal) previewModal.addEventListener('click', (e) => { if (e.target === previewModal) closeModal(); });

    // Word Listeners
    if (btnDownloadSingleModalDocx) btnDownloadSingleModalDocx.addEventListener('click', () => downloadExactOriginalDocx(false));
    if (btnDownloadBlankFromModal) btnDownloadBlankFromModal.addEventListener('click', () => downloadExactOriginalDocx(true));
    if (btnDownloadBlankDocx) btnDownloadBlankDocx.addEventListener('click', () => downloadExactOriginalDocx(true));
    if (btnDownloadBlankDocxFooter) btnDownloadBlankDocxFooter.addEventListener('click', () => downloadExactOriginalDocx(true));
    if (btnDownloadMasterDocx) btnDownloadMasterDocx.addEventListener('click', () => downloadExactOriginalDocx(false));
    if (btnDownloadMasterDocx2) btnDownloadMasterDocx2.addEventListener('click', () => downloadExactOriginalDocx(false));

    // PDF Listeners
    if (btnDownloadMasterPdf) btnDownloadMasterPdf.addEventListener('click', () => downloadDalilInPDF(false));
    if (btnDownloadMasterPdf2) btnDownloadMasterPdf2.addEventListener('click', () => downloadDalilInPDF(false));
    if (btnDownloadPdfModal) btnDownloadPdfModal.addEventListener('click', () => downloadDalilInPDF(false));
    if (btnDownloadBlankPdf) btnDownloadBlankPdf.addEventListener('click', () => downloadDalilInPDF(true));
    if (btnDownloadBlankPdfFooter) btnDownloadBlankPdfFooter.addEventListener('click', () => downloadDalilInPDF(true));
    if (btnDownloadBlankPdfFromModal) btnDownloadBlankPdfFromModal.addEventListener('click', () => downloadDalilInPDF(true));

    // --- PDF Generator Engine ---
    function downloadDalilInPDF(isBlank = false) {
        const titlePart = isBlank ? 'نموذج_فارغ' : (contractData.second_party_name || 'مكتمل');
        const fileName = 'عقد_شركة_دليل_ان_' + titlePart + '_' + Date.now() + '.pdf';

        showToast('جاري تحضير وإنشاء ملف PDF...', 'info');

        const tempContainer = document.createElement('div');
        tempContainer.className = 'contract-paper';
        tempContainer.style.background = '#ffffff';
        tempContainer.style.color = '#1e293b';
        tempContainer.style.padding = '35px 45px';
        tempContainer.style.fontFamily = "'Cairo', 'Times New Roman', serif";
        tempContainer.style.fontSize = '13px';
        tempContainer.style.lineHeight = '1.7';
        tempContainer.style.width = '794px'; // A4 pixel width
        tempContainer.innerHTML = buildDalilInContractHTML(isBlank);

        const opt = {
            margin:       [8, 10, 10, 10],
            filename:     fileName,
            image:        { type: 'jpeg', quality: 0.98 },
            html2canvas:  { scale: 2, useCORS: true, logging: false },
            jsPDF:        { unit: 'mm', format: 'a4', orientation: 'portrait' }
        };

        if (window.html2pdf) {
            window.html2pdf().set(opt).from(tempContainer).save().then(() => {
                showToast('تم تحميل العقد كملف PDF بنجاح!', 'success');
            }).catch(err => {
                console.error('PDF error:', err);
                showToast('تعذر توليد ملف PDF.', 'error');
            });
        } else {
            window.print();
        }
    }

    // --- Original Docx Template Replacer ---
    async function downloadExactOriginalDocx(isBlank = false) {
        const titlePart = isBlank ? 'نموذج_فارغ' : (contractData.second_party_name || 'مكتمل');
        const fileName = 'عقد_شركة_دليل_ان_' + titlePart + '_' + Date.now() + '.docx';

        if (isBlank) {
            showToast('جاري تحميل ملف العقد الأصلي فارغاً كما هو...', 'info');
            try {
                const arrayBuf = await getOriginalDocxBuffer();
                const blob = new Blob([arrayBuf], { type: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' });
                window.saveAs(blob, fileName);
                showToast('تم تحميل ملف العقد الأصلي فارغاً بنجاح!', 'success');
            } catch (err) {
                console.error("Fetch error:", err);
                showToast('تعذر الوصول إلى ملف العقد الأصلي.', 'error');
            }
            return;
        }

        showToast('جاري استبدال المسافات والسطور بالبيانات داخل الملف الأصلي...', 'info');

        try {
            const arrayBuffer = await getOriginalDocxBuffer();
            const zip = await JSZip.loadAsync(arrayBuffer);

            let docXml = await zip.file("word/document.xml").async("string");

            // Perform Exact In-place Replacements inside the original XML document

            if (contractData.ref_no) {
                docXml = docXml.replace(/REF\s*:\s*---\/26/g, 'REF : ' + contractData.ref_no);
            }

            if (contractData.date) {
                docXml = docXml.replace(/:05\/01\/2026/g, ':' + contractData.date);
                docXml = docXml.replace(/--\/01\/2026/g, contractData.date);
            }

            if (contractData.second_party_name) {
                docXml = docXml.replace(/-----------------------------------/g, contractData.second_party_name);
                docXml = docXml.replace(/----------------------------------------------------/g, contractData.second_party_name);
            }

            if (contractData.second_party_address) {
                docXml = docXml.replace(/:-------------------------------------------------------------------------------/g, ':' + contractData.second_party_address);
                docXml = docXml.replace(/--------------------------------------------------------------------------------------/g, contractData.second_party_address);
            }

            if (contractData.second_party_cr) {
                docXml = docXml.replace(/--------------/g, contractData.second_party_cr);
                docXml = docXml.replace(/---------------/g, contractData.second_party_cr);
            }

            if (contractData.iban_number) {
                docXml = docXml.replace(/------------------------------------------------------/g, contractData.iban_number);
                docXml = docXml.replace(/----------------------------------------------------------------------/g, contractData.iban_number);
            }

            if (contractData.commission_percent) {
                docXml = docXml.replace(/----\s*percent\s*\(\s*--\s*%/g, contractData.commission_percent + ' percent (' + contractData.commission_percent);
                docXml = docXml.replace(/---\s*٪/g, contractData.commission_percent);
                docXml = docXml.replace(/---/g, contractData.commission_percent);
            }

            if (contractData.arbitration_rules) {
                docXml = docXml.replace(/-----------------------------------------------------/g, contractData.arbitration_rules);
                docXml = docXml.replace(/--------------------------------------------------------------------------/g, contractData.arbitration_rules);
            }

            zip.file("word/document.xml", docXml);

            const outputBlob = await zip.generateAsync({
                type: "blob",
                mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
            });

            window.saveAs(outputBlob, fileName);
            showToast('تم تحميل الملف الأصلي محدثاً بالبيانات بنجاح!', 'success');

        } catch (err) {
            console.error("Zip replacement error:", err);
            showToast("حدث خطأ في معالجة المستند الأصلي.", "error");
        }
    }

    function buildDalilInContractHTML(isBlank = false) {
        const ref = isBlank ? '---/26' : (contractData.ref_no || '---/26');
        const date = isBlank ? '2026/01/05' : (contractData.date || '2026/01/05');
        const name = isBlank ? '----------------------------------------------------' : (contractData.second_party_name || '----------------------------------------------------');
        const addr = isBlank ? '--------------------------------------------------------------------------------------' : (contractData.second_party_address || '--------------------------------------------------------------------------------------');
        const cr = isBlank ? '--------------' : (contractData.second_party_cr || '--------------');
        const iban = isBlank ? '----------------------------------------------------------------------' : (contractData.iban_number || '----------------------------------------------------------------------');
        const comm = isBlank ? '---%' : (contractData.commission_percent || '---%');
        const arb = isBlank ? '--------------------------------------------------------------------------' : (contractData.arbitration_rules || '--------------------------------------------------------------------------');
        const sigName = isBlank ? '-----------------------' : (contractData.signatory_name || name);

        const p = contractData.payments;

        return `
            <div class="contract-header-ref">
                <div>REF : ${ref}</div>
                <div>تم تحرير هذا العقد في تاريخ: ${date}</div>
            </div>

            <div class="contract-title-center">
                شروط الاتفاقية / Terms of the Agreement
            </div>

            <div class="contract-body">
                <p><strong>تعريفات:</strong> الطرف الأول: هو شركة دليل ان – الطرف الثاني: هو المشترك (سواء كان شخص اعتباري أو فردي).</p>

                <p><strong>بيانات الطرف الأول السادة/ (دليل ان):</strong><br>
                سجل تجاري رقم: 1010000000</p>

                <p><strong>بيانات الطرف الثاني السادة/:</strong> <span class="contract-highlight">${name}</span><br>
                <strong>العنوان:</strong> <span class="contract-highlight">${addr}</span><br>
                <strong>سجل تجاري رقم:</strong> <span class="contract-highlight">${cr}</span></p>

                <p><strong>يلتزم المشترك (الطرف الثاني) بدفع المبالغ المستحقة إلى شركة دليل ان (الطرف الأول) للحساب البنكي التالي:</strong><br>
                Company Name: شركة دليل ان<br>
                IBAN Number: <span class="contract-highlight">${iban}</span></p>

                <hr style="margin:16px 0; border:0; border-top:1px solid #cbd5e1;">

                <p><strong>التمهيد:</strong> الطرف الأول شركة دليل ان ذات مسئولية محدودة ومتخصصة في مجال البيع بالجملة والتجزئة ووكيل بالعمولة والتسويق الإعلاني وتمتلك تطبيق (داو - دليل ان) المتخصص في ذات مجال ونشاط الشركة والذي يقدم العديد من الخدمات للشركات والأفراد الراغبين في الاستفادة من ذلك التطبيق في عرض منتجاتهم ونشاطهم على التطبيق وفقاً للخدمات المتاحة لهم عبر ذلك التطبيق لتمكين المستخدمين من الاستفادة من خدمات المشتركين ، وحيث أن الطرف الثاني (المشترك) يرغب في الاستفادة من تلك الخدمات الخاصة بالتطبيق والاستراك فيها بغية عرض منتجاته ونشاطه على التطبيق وفقاً لباقة الاشتراك المتفق عليها في هذا العقد – اتفق الطرفان، بعد التوصل إلى تفاهم مشترك، على ما يلي:</p>

                <ol style="padding-right:20px; margin-bottom:20px; line-height:1.8;">
                    <li>يعتبر التمهيد السابق جزء لا يتجزأ من هذا العقد ومكملاً ومتمماً له.</li>
                    <li>يمنح الطرف الأول للطرف الثاني حق استخدام التطبيق والوصول الكامل لكافة الخدمات وفقاً للباقة المشترك فيها، وعرض منتجاته وخدماته على التطبيق بما يحقق أكبر استفادة للطرف الثاني منه، ومنحه اسم مستخدم ورقم سري خاص به وذلك للاستفادة بخدمات التطبيق.</li>
                    <li>اتفق الطرفان على أن يكون اشتراك الطرف الثاني في التطبيق مجاناً لمدة سنة كاملة تبدأ من تاريخ الانطلاق الرسمي للتطبيق، ويُمنح خلالها حق الوصول إلى كافة خدمات التطبيق وعرض خدماته ومنتجاته عليه. كما يلتزم الطرف الثاني بدفع نسبة قدرها <strong>(<span class="contract-highlight">${comm}</span>)</strong> من عمليات المبيعات المحققة من خلال التطبيق لصالح الطرف الأول، وذلك وفقاً للآلية المتفق عليها بين الطرفين، دون استحقاق أي رسوم اشتراك خلال مدة السنة المجانية.</li>
                    <li>يحق للطرف الأول خصم ما تكبده من نفقات من إجمالي المبالغ المحصلة للطرف الثاني لديه ومنها على سبيل المثال التكاليف الأخرى وذلك في حال قيام العميل برفض استلام الطلب أو إرجاعه أو وجد به عيب أو غيرها من الأسباب التي تحول دون استلام العميل لطلبه والتي يترتب عليه رد الطلب، وفي حالة عدم وجود مبالغ محصلة لصالح الطرف الثاني فإنه يحق للطرف الأول مطالبة الطرف الثاني بهذه المبالغ مباشرة دون قيد أو شرط.</li>
                    <li>علاقة التطبيق والمعلن والمستفيد هي علاقة أطراف مستقلين ولا تعتبر هذه العلاقة علاقة شراكة أو توظيف أو وكالة بين أي منهم، وليس على التطبيق أي مسؤولية قبل المستفيدين في مواجهة مقدم الخدمة.</li>
                    <li>عند تأكيد الاشتراك في التطبيق فإن هذا التأكيد بمثابة تعاقد بينك وبين دليل ان حسب الشروط والمواصفات والأسر المعروضة مقابل الخدمة المشترك فيها.</li>
                    <li>يقتصر دور التطبيق في هذه الخدمة على تسهيل عملية الوصول للخدمة بين العمل ومقدم الخدمة (المشترك) دون أي التزامات أخرى.</li>
                    <li><strong>التزامات الطرف الثاني (المشترك):</strong>
                        <ul style="padding-right:20px; margin-top:6px;">
                            <li>يلتزم المستخدم بسداد جميع الرسوم المترتبة على خدمات التطبيق عند استحقاقها عن طريق التحويل البنكي.</li>
                            <li>عدم التعدي على أي مستخدم آخر داخل التطبيق أو محاولة الغش أو التدليس.</li>
                            <li>عدم نشر أو توزيع أي مواد تشهيرية أو هجومية أو انتهاكية أو عنصرية.</li>
                            <li>تحمل كافة المسؤولية القانونية المدنية والجنائية الناتجة عن أي مخالفة.</li>
                            <li>تجدد مدة العقد تلقائياً ما لم يخطر أحد الطرفين الآخر بعدم رغبته بالتجديد قبل انتهائه بشهرين على الأقل.</li>
                        </ul>
                    </li>
                </ol>

                <p><strong>قواعد التحكيم المتفق عليها:</strong> <span class="contract-highlight">${arb}</span></p>
                <p>عند التوقيع بالموافقة على ما جاء بهذه الاتفاقية فإنك توافق على ما جاء فيها ويعتبر بمثابة العقد الذي يحكم العلاقة بين الطرفين.</p>
            </div>

            <div class="contract-signatures">
                <div class="sig-box">
                    <h4>الطرف الأول: الاسم والتوقيع</h4>
                    <p style="font-weight:bold; margin-bottom:20px;">السيد / فيصل الرشيد</p>
                    <div class="sig-line"></div>
                </div>
                <div class="sig-box">
                    <h4>الطرف الثاني: الاسم والتوقيع</h4>
                    <p style="font-weight:bold; margin-bottom:20px;">السيد / ${sigName}</p>
                    <div class="sig-line"></div>
                </div>
            </div>

            <div style="margin:40px 0; border-top:2px dashed #94a3b8; text-align:center; position:relative;">
                <span style="background:#fff; padding:4px 12px; font-weight:bold; color:#64748b; font-size:0.8rem; position:relative; top:-12px;">ملحق عقد خدمات تسويقية (الصفحة الثانية)</span>
            </div>

            <div class="contract-title-center" style="font-size:1.3rem;">
                ملحق عقد خدمات تسويقية<br>
                <span style="font-size:1rem; color:#475569;">ADDENDUM TO MARKETING SERVICES CONTRACT</span>
            </div>

            <div class="contract-body">
                <p style="text-align:center; font-weight:bold;">Date / التاريخ: ${date}</p>
                <p><strong>First Party / الطرف الأول:</strong> شركة دليل ان (Dalil-in Com)</p>
                <p><strong>Second Party / الطرف الثاني:</strong> <span class="contract-highlight">${name}</span></p>

                <p>يعتبر هذا الملحق جزءاً لا يتجزأ من عقد الخدمات التسويقية، ويحدد الطرف الثاني طريقة الدفع المفضلة من الخيارات أدناه والمناسبة له وسيتم تطبيق رسوم البنك وفقاً للنسب المبينة:</p>

                <table>
                    <thead>
                        <tr>
                            <th>اختر / Select</th>
                            <th>طريقة الدفع / Payment Method</th>
                            <th>رسوم البنك لكل عمليات / Bank Charge for every Transaction</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr>
                            <td style="text-align:center;">${p.pay_knet ? '☑' : '☐'}</td>
                            <td><strong>KNET (كي نت)</strong></td>
                            <td>150 Fils Per Transaction</td>
                        </tr>
                        <tr>
                            <td style="text-align:center;">${p.pay_mastercard ? '☑' : '☐'}</td>
                            <td><strong>Mastercard (ماستركارد)</strong></td>
                            <td>2.25 % Per Transaction</td>
                        </tr>
                        <tr>
                            <td style="text-align:center;">${p.pay_visa ? '☑' : '☐'}</td>
                            <td><strong>Visa Card (فيزا كارد)</strong></td>
                            <td>2.25 % Per Transaction</td>
                        </tr>
                        <tr>
                            <td style="text-align:center;">${p.pay_applepay ? '☑' : '☐'}</td>
                            <td><strong>Apple Pay (أبل باي)</strong></td>
                            <td>40 Fils + 2.25 % Per Transaction</td>
                        </tr>
                        <tr>
                            <td style="text-align:center;">${p.pay_googlepay ? '☑' : '☐'}</td>
                            <td><strong>Google Pay (جوجل باي)</strong></td>
                            <td>2.25 % Per Transaction</td>
                        </tr>
                    </tbody>
                </table>

                <p><strong>الشروط والأحكام / Terms & Conditions:</strong></p>
                <ol style="padding-right:20px;">
                    <li>يوافق الطرف الثاني على تحمل رسوم البنك لطريقة الدفع.</li>
                    <li>يمكن اختيار أكثر من طريقة للدفع.</li>
                </ol>
            </div>

            <div class="contract-signatures" style="margin-top:20px;">
                <div class="sig-box">
                    <h4>First Party Signature / توقيع الطرف الأول</h4>
                    <div class="sig-line"></div>
                </div>
                <div class="sig-box">
                    <h4>Second Party name and Signature / اسم وتوقيع الطرف الثاني</h4>
                    <p style="font-weight:bold; margin-bottom:20px;">${sigName}</p>
                    <div class="sig-line"></div>
                </div>
            </div>
        `;
    }

    // Demo buttons
    if (btnDemo1) {
        btnDemo1.addEventListener('click', () => {
            if (uploadedImages.length >= MAX_IMAGES) return showToast('وصلت للحد الأقصى (5 صور).', 'error');
            const canvas = createSampleCanvas('صورة 1: سجل تجاري', 'اسم المشترك: شركة الأمل لتجارة التجزئة\nرقم السجل: 1010987654\nالعنوان: الرياض - طريق الملك فهد\nالمرجع: REF: 482/26');
            uploadedImages.push({ id: 'demo1_' + Date.now(), title: 'صورة 1 - السجل التجاري', url: canvas.toDataURL(), status: 'completed' });
            contractData.ref_no = '482/26';
            contractData.second_party_name = 'شركة الأمل لتجارة التجزئة';
            contractData.second_party_cr = '1010987654';
            contractData.second_party_address = 'الرياض - طريق الملك فهد';
            contractData.signatory_name = 'شركة الأمل لتجارة التجزئة';
            syncStateToForm();
            renderGallery();
            showToast('تم استخراج السجل التجاري وعنوان المشترك!', 'success');
        });
    }

    if (btnDemo2) {
        btnDemo2.addEventListener('click', () => {
            if (uploadedImages.length >= MAX_IMAGES) return showToast('وصلت للحد الأقصى (5 صور).', 'error');
            const canvas = createSampleCanvas('صورة 2: بيانات الحساب والنسبة', 'IBAN: SA0380000000123456789012\nنسبة المبيعات المتفق عليها: 12%\nقواعد التحكيم: مركز الكويت للتحكيم');
            uploadedImages.push({ id: 'demo2_' + Date.now(), title: 'صورة 2 - الآيبان والنسبة', url: canvas.toDataURL(), status: 'completed' });
            contractData.iban_number = 'SA0380000000123456789012';
            contractData.commission_percent = '12%';
            contractData.arbitration_rules = 'قواعد مركز الكويت للتحكيم التجاري';
            syncStateToForm();
            renderGallery();
            showToast('تم دمج الآيبان ونسبة المبيعات 12% في العقد!', 'success');
        });
    }

    if (btnDemo3) {
        btnDemo3.addEventListener('click', () => {
            if (uploadedImages.length >= MAX_IMAGES) return showToast('وصلت للحد الأقصى (5 صور).', 'error');
            const canvas = createSampleCanvas('صورة 3: ملحق طرق الدفع', 'طرق الدفع المفضلة:\n[x] KNET\n[x] Mastercard\n[x] Apple Pay');
            uploadedImages.push({ id: 'demo3_' + Date.now(), title: 'صورة 3 - ملحق طرق الدفع', url: canvas.toDataURL(), status: 'completed' });
            contractData.payments.pay_knet = true;
            contractData.payments.pay_mastercard = true;
            contractData.payments.pay_visa = true;
            contractData.payments.pay_applepay = true;
            contractData.payments.pay_googlepay = true;
            renderGallery();
            showToast('تم تحديد خيارات ملحق طرق الدفع!', 'success');
        });
    }

    function createSampleCanvas(title, text) {
        const canvas = document.createElement('canvas');
        canvas.width = 500; canvas.height = 300;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = '#1e293b'; ctx.fillRect(0,0,500,300);
        ctx.fillStyle = '#0f172a'; ctx.fillRect(10,10,480,280);
        ctx.fillStyle = '#10b981'; ctx.fillRect(10,10,480,45);
        ctx.fillStyle = '#ffffff'; ctx.font = 'bold 18px Cairo'; ctx.direction = 'rtl'; ctx.textAlign = 'right';
        ctx.fillText(title, 460, 40);
        ctx.fillStyle = '#e2e8f0'; ctx.font = '15px Cairo';
        const lines = text.split('\n');
        let y = 90;
        lines.forEach(l => { ctx.fillText(l, 460, y); y += 38; });
        return canvas;
    }

    syncStateToForm();
});
